// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount == 10 ether);
        uint256 initialBalance = address(c).balance;
        vm.deal(address(this), amount);
        (bool success, ) = address(c).call{value: amount}("");
        assertTrue(success);
        uint256 expectedBalance;
        if (block.number % 15 == 0) {
            // If block number is multiple of 15, the contract sends its entire balance back to the caller
            expectedBalance = initialBalance;
        } else {
            expectedBalance = initialBalance + amount;
        }
        assertTrue(address(c).balance == expectedBalance);
    }
}

